public class Main {
    public static void main(String[] args) {
        String nama = "Budi";
        int umur = 17;
        double tinggi = 165.456;

        System.out.println(String.format("Nama: %s, umur %d tahun", nama, umur));
        System.out.println(String.format("Tinggi: %.1f cm", tinggi));
        System.out.println(String.format("[%5d]", 42));
        System.out.println(String.format("[%-6s]", "ok"));
        System.out.printf("%s lulus: %b%n", nama, true);
    }
}

