cards.solution:
public class Main {
    public static void main(String[] args) {
        String nama = "Andi";
        int poin = 85;
        int peringkat = 2;
        System.out.println(String.format("%s: %d poin (peringkat %d)", nama, poin, peringkat));
        System.out.println(String.format("[%3d]", 5));
    }
}

